  dropmode: { … };
  selectable: { … };
  stats: { … };
  events: { … };
  drawable: Drawable;
  exploding?: cg.Exploding;
  hold: cg.Timer;
}

export interface State extends HeadlessState {
  dom: cg.Dom;
}

